def transform(grid):
    rows, cols = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] != 0}
    candidates = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            box = {(r, c), (r, c+1), (r+1, c), (r+1, c+1)}
            if box <= occupied:
                candidates.append((frozenset(box), 1))
            for missing, color in [((r,c),2), ((r+1,c),3), ((r,c+1),4), ((r+1,c+1),5)]:
                cells = box - {missing}
                if cells <= occupied:
                    candidates.append((frozenset(cells), color))
    by_cell = {p: [] for p in occupied}
    for piece in candidates:
        for p in piece[0]:
            by_cell[p].append(piece)
    solutions = []
    def cover(remaining, chosen):
        if not remaining:
            solutions.append(chosen[:])
            return
        p = min(remaining, key=lambda q: sum(piece[0] <= remaining for piece in by_cell[q]))
        for piece in by_cell[p]:
            if piece[0] <= remaining:
                cover(remaining - piece[0], chosen + [piece])
    cover(occupied, [])
    if len(solutions) != 1:
        raise ValueError(f'expected unique tile cover, got {len(solutions)}')
    out = [[0] * cols for _ in range(rows)]
    for cells, color in solutions[0]:
        for r, c in cells:
            out[r][c] = color
    return out

